"""The mutants of src/cir/cir_serializer.c: (name, text that occurs exactly once, its replacement). A name starts with its tag.
Used by run_mut.py (set MUT_TIMEOUT=60: a mutant that hangs is killed by the timeout). The mutants that cannot be told from
the original are marked (equivalent) and explained in docs/audit; the ones that need 2**32 elements to show are marked
(unreachable) - they are not equivalent, the tests cannot build such a function."""
SRC = 'src/cir/cir_serializer.c'
TESTS = ['test_cir_serializer', 'test_cir_builder_hostile', 'test_disasm_to_cir']

